#' Plots adjustment and trend filters from an X-13ARIMA-SEATS SEATS seasonal
#' adjustment run in a single plot. 
#'
#' Generate plot of the concurrent and symmetric filters for the seasonally adjusted
#  series and trend component from a SEATS adjustment from a \code{seas} object 
#' generated by the \code{seasonal} package. 
#' For more information on SEATS as implemented in X-13ARIMA-SEATS, 
#' \insertCite{@see Section 7.14 of @Census2025}{blsplotGG}.
#'
#' Version 1.10, 2/10/2026
#'
#' @param seas_obj \code{seas} object generated from a call of \code{seas} on a single time series
#'        This is a required entry.
#' @param overall_title Character string; main title of plot. 
#'        Default is \code{"SEATS Adjustment and Trend Filters"}.
#' @param this_y_label Character string; y-axis label for plot.
#'        Default is no y axis label.
#' @param this_x_label Label for X axis. Default is \code{"Index"}.
#' @param this_x_concurrent_breaks Numeric array with tick marks for the X-axis for 
#'        concurrent filter plots. 
#'        Default is generated by the plotting routine.
#' @param this_x_symmetric_breaks Numeric array with tick marks for the X-axis for 
#'        symmetric filter plots. 
#'        Default is generated by the plotting routine.
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines.
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param title_size integer scalar; Size of the plot title for individual panels. 
#'        Default is \code{10}; the overall title size will be \code{title_size + 10}.
#' @param point_color Character string; color used for points in the plot.  
#'        Default is \code{'steelblue'}. 
#' @param point_size Integer scalar; relative size of points in filter plot.
#'        Default is \code{1.0}.
#' @param point_shape Integer scalar; code for the shape of points in filter plot.
#'        Default is \code{20}, a small filled circle.
#' @return A \code{ggplot} object that generates a plot of the adjustment and trend 
#'         concurrent and symmetric filters from a SEATS seasonal adjustment from X-13ARIMA-SEATS. 
#'         If SEATS seasonal adjustment (with \code{seats.finite = "yes"}) not producted,  
#'         print out error message and return NULL. 
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' shoes_seats_seas <- 
#'    seasonal::seas(shoes2008, arima.model = "(0 1 1)(0 1 1)", 
#'                   transform.function = "log", 
#'                   forecast.maxlead = 36,
#'                   check.print = c( 'pacf', 'pacfplot' ), 
#'                   seats.finite = "yes",
#'                   seats.save = c( 'fac', 'faf', 'ftc', 'ftf' ) )
#' p_shoe_seats_filter <- 
#'   plot_seats_filter_all(shoes_seats_seas, 
#'		 overall_title = "US Shoe Sales",
#'		 point_color = "darkgreen",
#'     this_x_symmetric_breaks = seq(-96,96,24))
#' @importFrom magrittr %>%
#' @importFrom rlang .data
#' @importFrom Rdpack reprompt
#' @export
plot_seats_filter_all <- function(
	seas_obj = NULL, 
	overall_title = "SEATS Adjustment and Trend Filters", 
	this_y_label = NULL, 
	this_x_label = "Index", 
	this_x_concurrent_breaks = NULL,
	this_x_symmetric_breaks = NULL,
	do_grid = FALSE,
	do_background = FALSE,
	title_size = 10,
	point_color = "steelblue",
	point_size = 1.25,
	point_shape = 20) {
    # Author: Brian C. Monsell (OEUS) Version 1.10, 2/10/2026
	
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }
	
	if (!("seatsadj" %in% names(seasonal::udg(seas_obj)))) {
		cat("Must use SEATS to generate seasonal adjustment")
		return(NULL)
	}
    
	good_values     <- c("sa", "trn")
	good_filters    <- c("symmetric", "concurrent")
	
	this_filter_plot <- list()
	
	for (i in 1:2) {
		this_series <- good_values[i]  
		for (j in 1:2) {
			this_filter <- good_filters[j]
			this_key <- paste(this_series, this_filter, sep = ".")
			if (this_filter == "concurrent") {
				this_x_breaks <- this_x_concurrent_breaks
			} else {
				this_x_breaks <- this_x_symmetric_breaks
			}
			
			this_title <- this_filter
			if (this_series == "sa") {
				this_title <- paste0(this_title, " Adjustment ")
			} else {
				this_title <- paste0(this_title, " Trend ")
			}
			this_title <- stringr::str_to_title(paste0(this_title, "Filter"))
			
			this_filter_plot[[this_key]] <- 
				plot_seats_filter(
					seas_obj,
					this_series,
					this_filter,
					main_title = this_title, 
					sub_title = NULL, 
					this_y_label = this_y_label,
					this_x_label = this_x_label,
					this_x_breaks = this_x_breaks,
					do_grid = do_grid,
					do_background = do_background,
					title_size = title_size,
					point_color = point_color,
					point_size = point_size,
					point_shape = point_shape) + 
				ggplot2::theme(axis.text.x = ggplot2::element_text(size = title_size), 
				               axis.text.y = ggplot2::element_text(size = title_size)) 
		}
	}
	
	p_final <- 
		ggpubr::ggarrange(plotlist = this_filter_plot, 
				nrow = 2, 
				ncol = 2)

	if (!is.null(overall_title)) {
		p_final <- 
			ggpubr::annotate_figure(p_final, 
				top = ggpubr::text_grob(overall_title, size = title_size + 2))
	}

	return(p_final)
}
	
